while($line = fgets(STDIN)) {
    echo preg_replace_callback('/(?P<num>\b[1-9]?[0-9]+)\b/', function ($m) {
        $num = $m['num'];
        return to漢数字($num);
    }, $line);
}

function to漢数字(int $n): string
{
    $kansuji = [
        0 => '〇',
        1 => '一',
        2 => '二',
        3 => '三',
        4 => '四',
        5 => '五',
        6 => '六',
        7 => '七',
        8 => '八',
        9 => '九',
    ];

    do {
        $_ = (int)$n % 10;
        $digits[] = $kansuji[$_];
        $n = $n / 10;
    } while($n >= 1);

    return implode(array_reverse($digits));
}
